const e="myocardial-infarction",i="Острый коронарный синдром / Инфаркт миокарда",t="#ef4444",r=[{id:"troponin_i",label:"Тропонин I",layer:"raw",type:"lab",unit:"нг/мл",normal:"<0.04",value:2.5,group:"cardiac_marker",description:"Высокочувствительный маркер некроза кардиомиоцитов. >0.04 нг/мл — диагностический критерий ОИМ. Динамика через 3–6 ч обязательна."},{id:"troponin_t",label:"Тропонин T",layer:"raw",type:"lab",unit:"нг/мл",normal:"<0.01",value:1.8,group:"cardiac_marker",description:"Маркер повреждения миокарда. Подъём через 3–4 ч, пик 12–24 ч. hs-cTnT позволяет исключить ОИМ за 1–3 ч."},{id:"ck_mb",label:"КФК-МВ",layer:"raw",type:"lab",unit:"Ед/л",normal:"<25",value:45,group:"cardiac_marker",description:"Фермент миокарда. Менее специфичен, чем тропонины. Используется для оценки реперфузии после ЧКВ."},{id:"myoglobin",label:"Миоглобин",layer:"raw",type:"lab",unit:"нг/мл",normal:"<70",value:120,group:"cardiac_marker",description:"Ранний маркер (<2 ч), но неспецифичен. Быстро очищается, нормализуется за 24 ч."},{id:"bnp",label:"NT-proBNP",layer:"raw",type:"lab",unit:"пг/мл",normal:"<125",value:850,group:"heart_failure",description:"Маркер растяжения желудочков. >125 пг/мл — ХСН, >1800 — тяжёлая ОЛЖН. Прогностический фактор смертности."},{id:"ldl",label:"ЛПНП",layer:"raw",type:"lab",unit:"ммоль/л",normal:"<3.0",value:4.2,group:"lipid",description:"ЛПНП — основной фактор риска атеросклероза. >3.0 — повышенный риск, >4.9 — очень высокий."},{id:"creatinine",label:"Креатинин",layer:"raw",type:"lab",unit:"мкмоль/л",normal:"62-115",value:105,group:"kidney",description:"Маркер функции почек. Рост при кардиогенном шоке из-за гипоперфузии."},{id:"glucose",label:"Глюкоза",layer:"raw",type:"lab",unit:"ммоль/л",normal:"3.9-6.1",value:8.5,group:"metabolism",description:"Гипергликемия при ОИМ — стрессовый ответ. >10 ммоль/л ухудшает прогноз."},{id:"hemoglobin",label:"Гемоглобин",layer:"raw",type:"lab",unit:"г/л",normal:"М 130-160",value:142,group:"cbc",description:"Анемия усугубляет ишемию миокарда. Гемоглобин <100 г/л — фактор риска смертности."},{id:"wbc",label:"Лейкоциты",layer:"raw",type:"lab",unit:"×10⁹/л",normal:"4-9",value:11.2,group:"cbc",description:"Лейкоцитоз при ОИМ — воспалительный ответ. >11×10⁹/л ассоциирован с плохим прогнозом."},{id:"crp",label:"СРБ",layer:"raw",type:"lab",unit:"мг/л",normal:"<5",value:18,group:"inflammation",description:"Маркер воспаления. Высокий СРБ при ОИМ — признак нестабильности бляшки и риска рецидива."},{id:"ecg_stemi_ant",label:"ЭКГ: ST↑ передние отведения",layer:"raw",type:"instrumental",group:"ecg",description:"ST↑ в V1–V4 — передний ОИМ (ЛВА). Требует экстренной реваскуляризации <12 ч."},{id:"ecg_stemi_inf",label:"ЭКГ: ST↑ нижние отведения",layer:"raw",type:"instrumental",group:"ecg",description:"ST↑ в II, III, aVF — нижний ОИМ (ПЖА). Часто сопровождается ПБПНПГ и БП."},{id:"ecg_stemi_lat",label:"ЭКГ: ST↑ боковые отведения",layer:"raw",type:"instrumental",group:"ecg",description:"ST↑ в I, aVL, V5–V6 — боковой ОИМ. Высокий риск ОЛЖН и механических осложнений."},{id:"ecg_stemi_post",label:"ЭКГ: ST↑ задняя стенка (V7-V9)",layer:"raw",type:"instrumental",group:"ecg",description:"ST↑ в V7–V9 — задний ОИМ. Часто сопровождается ST↓ в V1–V3."},{id:"ecg_nstemi",label:"ЭКГ: ST↓ / инверсия T без ST↑",layer:"raw",type:"instrumental",group:"ecg",description:"ST↓ или инверсия T без ST↑ — NSTEMI. Требует ранней инвазивной стратегии <72 ч."},{id:"ecg_new_lbbb",label:"ЭКГ: новая БПНПГ",layer:"raw",type:"instrumental",group:"ecg",description:"Новая БПНПГ при боли за грудиной — эквивалент STEMI. Требует немедленной реваскуляризации."},{id:"echo_wma",label:"ЭхоКГ: нарушение сократимости",layer:"raw",type:"instrumental",group:"echo",description:"Нарушение региональной сократимости — подтверждение ишемии/некроза. Определяет поражённую зону."},{id:"echo_ef",label:"ЭхоКГ: ФВ ЛЖ",layer:"raw",type:"instrumental",unit:"%",normal:">55",value:42,group:"echo",description:"ФВ ЛЖ — ключевой прогностический параметр. <40% — снижение ФВ, <30% — тяжёлая дисфункция."},{id:"coronary_angiography",label:"Коронарография",layer:"raw",type:"instrumental",group:"invasive",description:"Золотой стандарт диагностики. Определяет степень стеноза и тактику: ЧКВ или АКШ."},{id:"chest_pain",label:"Боль за грудиной",layer:"findings",type:"symptom",severity:"интенсивная",description:"Компрессионная боль за грудиной >20 мин — типичный признак ОИМ. Может сопровождаться потливостью."},{id:"chest_pain_radiation",label:"Иррадиация боли в левую руку/челюсть",layer:"findings",type:"symptom",description:"Иррадиация в левую руку, челюсть, межлопаточную область — патогномонична для ОИМ."},{id:"diaphoresis",label:"Потливость",layer:"findings",type:"symptom",description:"Обильная потливость — вегетативный ответ на ишемию миокарда и боль."},{id:"dyspnea",label:"Одышка",layer:"findings",type:"symptom",description:"Одышка при ОИМ — признак ОЛЖН, особенно при переднем ОИМ с большой зоной поражения."},{id:"nausea",label:"Тошнота/рвота",layer:"findings",type:"symptom",description:"Тошнота и рвота при нижнем ОИМ — рефлекс через блуждающий нерв. Может маскировать диагноз."},{id:"tachycardia",label:"Тахикардия",layer:"findings",type:"sign",description:"Тахикардия — компенсаторный ответ на снижение УО. При кардиогенном шоке >100/мин."},{id:"hypotension",label:"Артериальная гипотензия",layer:"findings",type:"sign",severity:"тяжёлая",description:"САД <90 — кардиогенный шок. Требует инотропов/вазопрессоров и срочной реваскуляризации."},{id:"pallor",label:"Бледность кожных покровов",layer:"findings",type:"sign",description:"Бледность — периферическая вазоконстрикция при кардиогенном шоке."},{id:"heart_failure_signs",label:"Признаки ОЛЖН",layer:"findings",type:"finding",description:"Хрипы, застой в лёгких, отёки — признаки ОЛЖН при обширном ОИМ."},{id:"cardiogenic_shock",label:"Кардиогенный шок",layer:"findings",type:"complication",severity:"критическая",description:"Смертность 40–50%. Требует ИАБК, инотропов, срочной ЧКВ. Killip IV."},{id:"malignant_arrhythmia",label:"Жизнеугрожающая аритмия",layer:"findings",type:"complication",description:"ФЖ, ТПЖ, асистолия — основная причина внезапной смерти при ОИМ. Требует дефибрилляции."},{id:"mechanical_complication",label:"Механическое осложнение ОИМ",layer:"findings",type:"complication",description:"Разрыв межжелудочковой перегородки, свободной стенки, ПМК — требует экстренной хирургии."},{id:"stemi",label:"STEMI (ОИМ с подъёмом ST)",layer:"hypotheses",type:"diagnosis",prevalence:"30% ОКС",ptp:"high",description:"STEMI — острый инфаркт миокарда с элевацией ST. Требует экстренной реваскуляризации <12 ч."},{id:"nstemi",label:"NSTEMI (ОИМ без подъёма ST)",layer:"hypotheses",type:"diagnosis",prevalence:"40% ОКС",ptp:"high",description:"NSTEMI — инфаркт без элевации ST. Повышение тропонинов, ишемия. Ранняя инвазивная стратегия <72 ч."},{id:"unstable_angina",label:"Нестабильная стенокардия",layer:"hypotheses",type:"diagnosis",prevalence:"25% ОКС",ptp:"high",description:"Нестабильная стенокардия — ишемия без повышения тропонинов. Высокий риск прогрессирования в ОИМ."},{id:"pericarditis",label:"Острый перикардит",layer:"hypotheses",type:"diagnosis",prevalence:"5%",ptp:"medium",description:"Острый перикардит — воспаление перикарда. Диффузный ST↑, PR↓, шум трения. Отличить от ОИМ."},{id:"aortic_dissection",label:"Расслоение аорты",layer:"hypotheses",type:"diagnosis",prevalence:"0.5%",ptp:"low",description:'Расслоение аорты — внезапная "разрывная" боль. Может имитировать ОИМ при вовлечении коронарных артерий.'},{id:"pulmonary_embolism",label:"ТЭЛА",layer:"hypotheses",type:"diagnosis",prevalence:"1-2%",ptp:"medium",description:"ТЭЛА — острая закупорка лёгочной артерии. Одышка, тахикардия, гипоксемия. Может сопровождать ОИМ."},{id:"pneumothorax",label:"Пневмоторакс",layer:"hypotheses",type:"diagnosis",prevalence:"0.5%",ptp:"low",description:"Пневмоторакс — скопление воздуха в плевральной полости. Острая одышка, боль в грудной клетке."},{id:"esophageal_spasm",label:"Пищеводный спазм",layer:"hypotheses",type:"diagnosis",prevalence:"редко",ptp:"low",description:'Пищеводный спазм — "коронарный" тип боли. Отличить по отсутствию ЭКГ-изменений, ответу на нитраты.'},{id:"diff_stemi_vs_nstemi",label:"STEMI vs NSTEMI",layer:"differential",type:"comparison"},{id:"diff_omi_vs_pericarditis",label:"ОИМ vs Перикардит",layer:"differential",type:"comparison"},{id:"diff_omi_vs_aortic_dissection",label:"ОИМ vs Расслоение аорты",layer:"differential",type:"comparison"},{id:"diff_omi_vs_pulmonary_embolism",label:"ОИМ vs ТЭЛА",layer:"differential",type:"comparison"},{id:"diff_algorithm_oks",label:"Алгоритм диффдиагностики ОКС",layer:"differential",type:"algorithm"},{id:"meta_primary_pci",label:"Мета-анализ: первичная ПТКА при STEMI",layer:"evidence",type:"meta-analysis",grade:"A",year:2019,n:4500,description:"Мета-анализ первичной ЧКВ — превосходит тромболизис при STEMI. Золотой стандарт реперфузии."},{id:"rct_ticagrelor",label:"RCT: тикагрелор vs клопидогрель при ОКС",layer:"evidence",type:"rct",grade:"A",year:2009,n:18624,description:"PLATO (2009) — тикагрелор снижает смертность при ОИМ по сравнению с клопидогрелем."},{id:"guideline_esc_2023",label:"ESC Guidelines: ACS 2023",layer:"evidence",type:"guideline",grade:"A",year:2023,description:"ESC Guidelines 2023 — управление острыми коронарными синдромами без элевации ST."},{id:"guideline_acc_aha_2022",label:"ACC/AHA Guidelines: STEMI 2022",layer:"evidence",type:"guideline",grade:"A",year:2022,description:"ACC/AHA Guidelines 2022 — руководство по управлению пациентами с ОИМ с элевацией ST."},{id:"rct_thrombolysis",label:"RCT: тромболизис при STEMI",layer:"evidence",type:"rct",grade:"A",year:1993,n:58600,description:"GISSI, ISIS-2 — тромболизис снижает смертность при STEMI. Фибринолитики в первые часы."},{id:"cohort_nstemi_invasive",label:"Когорта: инвазивная стратегия при NSTEMI",layer:"evidence",type:"cohort",grade:"B",year:2020,n:8500,description:"Когортные исследования — ранняя инвазивная стратегия <72 ч снижает смертность при NSTEMI."}],a=[{source:"troponin_i",target:"stemi",type:"key_marker",weight:.95},{source:"troponin_i",target:"nstemi",type:"key_marker",weight:.95},{source:"troponin_t",target:"stemi",type:"key_marker",weight:.95},{source:"troponin_t",target:"nstemi",type:"key_marker",weight:.95},{source:"troponin_i",target:"unstable_angina",type:"discriminates",weight:.9},{source:"ecg_stemi_ant",target:"stemi",type:"key_marker",weight:1},{source:"ecg_stemi_inf",target:"stemi",type:"key_marker",weight:1},{source:"ecg_stemi_lat",target:"stemi",type:"key_marker",weight:1},{source:"ecg_stemi_post",target:"stemi",type:"key_marker",weight:1},{source:"ecg_nstemi",target:"nstemi",type:"key_marker",weight:.85},{source:"ecg_nstemi",target:"unstable_angina",type:"key_marker",weight:.8},{source:"ecg_new_lbbb",target:"stemi",type:"key_marker",weight:.9},{source:"chest_pain",target:"stemi",type:"supports",weight:.85},{source:"chest_pain",target:"nstemi",type:"supports",weight:.8},{source:"chest_pain",target:"unstable_angina",type:"supports",weight:.85},{source:"chest_pain",target:"pericarditis",type:"supports",weight:.7},{source:"chest_pain",target:"aortic_dissection",type:"supports",weight:.75},{source:"chest_pain",target:"pulmonary_embolism",type:"supports",weight:.5},{source:"chest_pain_radiation",target:"stemi",type:"supports",weight:.8},{source:"chest_pain_radiation",target:"nstemi",type:"supports",weight:.75},{source:"diaphoresis",target:"stemi",type:"supports",weight:.7},{source:"diaphoresis",target:"nstemi",type:"supports",weight:.6},{source:"dyspnea",target:"stemi",type:"supports",weight:.65},{source:"dyspnea",target:"nstemi",type:"supports",weight:.6},{source:"dyspnea",target:"pulmonary_embolism",type:"supports",weight:.85},{source:"nausea",target:"stemi",type:"supports",weight:.5},{source:"tachycardia",target:"stemi",type:"supports",weight:.6},{source:"tachycardia",target:"nstemi",type:"supports",weight:.55},{source:"tachycardia",target:"pulmonary_embolism",type:"supports",weight:.7},{source:"hypotension",target:"stemi",type:"supports",weight:.75},{source:"hypotension",target:"cardiogenic_shock",type:"causes",weight:.9},{source:"pallor",target:"stemi",type:"supports",weight:.5},{source:"heart_failure_signs",target:"stemi",type:"complication_of",weight:.7},{source:"heart_failure_signs",target:"nstemi",type:"complication_of",weight:.65},{source:"cardiogenic_shock",target:"stemi",type:"complication_of",weight:.85},{source:"malignant_arrhythmia",target:"stemi",type:"complication_of",weight:.8},{source:"mechanical_complication",target:"stemi",type:"complication_of",weight:.6},{source:"ck_mb",target:"stemi",type:"supports",weight:.7},{source:"ck_mb",target:"nstemi",type:"supports",weight:.7},{source:"myoglobin",target:"stemi",type:"supports",weight:.6},{source:"bnp",target:"heart_failure_signs",type:"causes",weight:.8},{source:"ldl",target:"stemi",type:"associated",weight:.5},{source:"ldl",target:"nstemi",type:"associated",weight:.5},{source:"wbc",target:"stemi",type:"associated",weight:.4},{source:"crp",target:"stemi",type:"associated",weight:.45},{source:"echo_wma",target:"stemi",type:"supports",weight:.9},{source:"echo_wma",target:"nstemi",type:"supports",weight:.85},{source:"echo_ef",target:"stemi",type:"supports",weight:.75},{source:"coronary_angiography",target:"stemi",type:"confirms",weight:1},{source:"coronary_angiography",target:"nstemi",type:"confirms",weight:1},{source:"stemi",target:"diff_stemi_vs_nstemi",type:"compared_in",weight:1},{source:"nstemi",target:"diff_stemi_vs_nstemi",type:"compared_in",weight:1},{source:"stemi",target:"diff_omi_vs_pericarditis",type:"compared_in",weight:1},{source:"pericarditis",target:"diff_omi_vs_pericarditis",type:"compared_in",weight:1},{source:"stemi",target:"diff_omi_vs_aortic_dissection",type:"compared_in",weight:1},{source:"aortic_dissection",target:"diff_omi_vs_aortic_dissection",type:"compared_in",weight:1},{source:"stemi",target:"diff_omi_vs_pulmonary_embolism",type:"compared_in",weight:1},{source:"pulmonary_embolism",target:"diff_omi_vs_pulmonary_embolism",type:"compared_in",weight:1},{source:"diff_algorithm_oks",target:"diff_stemi_vs_nstemi",type:"includes",weight:1},{source:"diff_algorithm_oks",target:"diff_omi_vs_pericarditis",type:"includes",weight:1},{source:"diff_algorithm_oks",target:"diff_omi_vs_aortic_dissection",type:"includes",weight:1},{source:"diff_algorithm_oks",target:"diff_omi_vs_pulmonary_embolism",type:"includes",weight:1},{source:"stemi",target:"meta_primary_pci",type:"treated_in",weight:1},{source:"stemi",target:"rct_ticagrelor",type:"treated_in",weight:1},{source:"stemi",target:"guideline_esc_2023",type:"covered_in",weight:1},{source:"stemi",target:"guideline_acc_aha_2022",type:"covered_in",weight:1},{source:"stemi",target:"rct_thrombolysis",type:"treated_in",weight:1},{source:"nstemi",target:"rct_ticagrelor",type:"treated_in",weight:1},{source:"nstemi",target:"guideline_esc_2023",type:"covered_in",weight:1},{source:"nstemi",target:"cohort_nstemi_invasive",type:"treated_in",weight:1},{source:"unstable_angina",target:"guideline_esc_2023",type:"covered_in",weight:1},{source:"diff_stemi_vs_nstemi",target:"guideline_esc_2023",type:"described_in",weight:1}],s={stemi:{description:"STEMI (ST-elevation myocardial infarction) — острый инфаркт миокарда с подъёмом сегмента ST на ЭКГ, обусловленный полной окклюзией коронарной артерии тромбом. Требует экстренной реваскуляризации в первые 12 часов.",criteria:["Боль за грудиной >20 мин","ST↑ ≥2 мм в 2 соседних отведениях","Тропонин повышен","Новая БПНПГ с клиникой ОИМ"],prevalence:"30% всех случаев ОКС",complications:["Кардиогенный шок","Жизнеугрожающая аритмия (ЖТ, фибрилляция желудочков)","Острая ЛЖН","Механическое осложнение (разрыв МЖП, ПМ)","Тромбоэмболия"],treatment:["Аспирин 300 мг + тикагрелор 180 мг (или клопидогрель 600 мг)","Первичная ПТКА в течение 90 мин (door-to-balloon)","Гепарин (ФМГ или НФГ)","Статин высокой интенсивности (аторвастатин 80 мг)","Бета-блокаторы (если нет противопоказаний)","АПФ-ингибиторы","Нитраты при боли/ишемии"],followup:"Кардиолог через 1-2 недели, контроль ЛП, ЭхоКГ через 4-6 недель, реабилитация"},nstemi:{description:"NSTEMI (Non-ST-elevation myocardial infarction) — инфаркт миокарда без подъёма ST, с повышением тропонинов. Вызывается частичной окклюзией или эмболизацией тромба.",criteria:["Клиника ишемии","Тропонин повышен","Отсутствие ST↑ на ЭКГ","Могут быть ST↓ или инверсия T"],prevalence:"40% всех случаев ОКС",complications:["Рецидив ишемии","ОИМ повторный","Острая ЛЖН","Смерть (высокий риск при отсроченной стратегии)"],treatment:["Аспирин + тикагрелор/клопидогрель","Гепарин","Инвазивная стратегия в течение 24-72 ч для высокого риска","Статины высокой интенсивности","Бета-блокаторы","АПФ-ингибиторы"],followup:"GRACE-оценка риска, ранняя коронарография для high-risk"},unstable_angina:{description:"Нестабильная стенокардия — клиника острой ишемии миокарда без повышения тропонинов. Предвестник ОИМ.",criteria:["Боль в груди в покое или нарастающая","Новая стенокардия","Тропонин в норме","Изменения на ЭКГ возможны"],prevalence:"25% ОКС",complications:["Прогрессирование в NSTEMI/STEMI","Внезапная сердечная смерть"],treatment:["Аспирин + П2Y12-ингибитор","Гепарин","Нитраты","Бета-блокаторы","Статины","Выборочная инвазивная стратегия"],followup:"Оценка риска, коронарография при высоком риске"}},o={diff_stemi_vs_nstemi:{headers:["Признак","STEMI","NSTEMI"],rows:[{feature:"ЭКГ",stemi:"ST↑ ≥2 мм в 2 отведениях",nstemi:"ST↓, инверсия T, или норма"},{feature:"Тропонин",stemi:"Повышен",nstemi:"Повышен"},{feature:"Механизм",stemi:"Полная окклюзия",nstemi:"Частичная окклюзия/эмболия"},{feature:"Срочность",stemi:"Первичная ПТКА <90 мин",nstemi:"Инвазия 24-72 ч (high-risk)"},{feature:"Тромболизис",stemi:"Показан при отсутствии ПТКА",nstemi:"Не показан"},{feature:"Прогноз",stemi:"Более тяжёлый (больше осложнений)",nstemi:"Зависит от риска (GRACE)"}]},diff_omi_vs_pericarditis:{headers:["Признак","ОИМ (STEMI)","Острый перикардит"],rows:[{feature:"Характер боли",omi:"Давящая, иррадиация в руку",pericarditis:"Острая, усиливается при вдохе, лежа"},{feature:"ЭКГ",omi:"ST↑ выпуклый, локализованный",pericarditis:"ST↑ вогнутый, диффузный во всех отведениях"},{feature:"Тропонин",omi:"Значительно повышен",pericarditis:"Умеренно повышен или норма"},{feature:"Шум трения",omi:"Отсутствует",pericarditis:"Присутствует (патогномонично)"},{feature:"PR-интервал",omi:"Норма",pericarditis:"Депрессия (часто)"},{feature:"Лечение",omi:"Антикоагулянты, ПТКА",pericarditis:"НПВП, колхицин (НЕ антикоагулянты!)"}]},diff_omi_vs_aortic_dissection:{headers:["Признак","ОИМ","Расслоение аорты"],rows:[{feature:"Характер боли",omi:"Давящая, за грудиной",aortic_dissection:"Максимальная интенсивность сразу, 'разрыв'"},{feature:"Иррадиация",omi:"Левая рука, челюсть",aortic_dissection:"Спина, живот, конечности"},{feature:"Разница АД",omi:"Нет",aortic_dissection:">20 мм рт.ст. между руками"},{feature:"Неврология",omi:"Нет",aortic_dissection:"Инсульт, параплегия (причина неясна)"},{feature:"ЭКГ",omi:"ST↑",aortic_dissection:"Норма или некритичные изменения"},{feature:"КТ-ангиография",omi:"Не требуется",aortic_dissection:"Золотой стандарт"}]}},n={meta_primary_pci:{title:"Primary percutaneous coronary intervention versus thrombolysis for STEMI: a systematic review and meta-analysis",authors:"Keeley EC et al.",journal:"Lancet",year:2019,n:4500,design:"Meta-analysis of 23 RCTs",grade:"A",key_findings:["Первичная ПТКА снижает смертность на 27% vs тромболизис (OR 0.73, 95% CI 0.62-0.86)","Снижение реинфаркта на 62% (OR 0.38)","Снижение инсульта на 50% (OR 0.50)","Door-to-balloon <90 мин — ключевой показатель качества"],quality:"Высокое (GRADE: A)"},rct_ticagrelor:{title:"Ticagrelor versus clopidogrel in patients with acute coronary syndromes (PLATO)",authors:"Wallentin L et al.",journal:"N Engl J Med",year:2009,n:18624,design:"Double-blind RCT",grade:"A",key_findings:["Тикагрелор снижает смертность от сосудистых причин на 21% vs клопидогрель (9.8% vs 11.7%)","Снижение ОИМ на 16%","Повышение риска не-CABG кровотечений (4.5% vs 3.8%)","Контраиндикация: тяжёлая печёночная недостаточность, ингибиторы CYP3A4"],quality:"Высокое (GRADE: A, крупнейшее исследование в ОКС)"},guideline_esc_2023:{title:"2023 ESC Guidelines for the management of acute coronary syndromes",authors:"Byrne RA et al.",journal:"Eur Heart J",year:2023,design:"Clinical guideline",grade:"A",key_findings:["STEMI: первичная ПТКА — метод выбора, тромболизис — только при невозможности ПТКА в течение 120 мин","NSTEMI: инвазивная стратегия в течение 24 ч для GRACE >140","Двойная антитромбоцитарная терапия 12 месяцев (аспирин + тикагрелор/прасугрель)","Статины высокой интенсивности для всех пациентов"],quality:"Высокое (GRADE: A, ESC Class I recommendations)"},rct_thrombolysis:{title:"Effectiveness of intravenous thrombolytic treatment in acute myocardial infarction (GISSI, ISIS-2, AIMS pooled)",authors:"GISSI, ISIS-2, AIMS Collaborative Groups",journal:"Lancet",year:1993,n:58600,design:"Pooled analysis of mega-RCTs",grade:"A",key_findings:["Тромболизис снижает смертность на 18% при STEMI","Аспирин + тромболизис: снижение смертности на 42%","Чем раньше — тем лучше: 'время — мышца'","Показан при STEMI без доступа к ПТКА в течение 120 мин"],quality:"Высокое (GRADE: A, исторические mega-RCTs)"}},p={stemi:[{time:0,event:"Начало боли",troponin:.02,ecg:"Норма",symptom:"Боль за грудиной"},{time:30,event:"30 мин",troponin:.05,ecg:"ST↑ V1-V4",symptom:"Усиление боли, пот"},{time:60,event:"1 час",troponin:.8,ecg:"ST↑ V1-V6",symptom:"Тахикардия, тошнота"},{time:90,event:"ПТКА",troponin:1.5,ecg:"ST↓ после реканализации",symptom:"Уменьшение боли"},{time:180,event:"3 часа",troponin:8,ecg:"Q-волны V1-V4",symptom:"Стабилизация"},{time:360,event:"6 часов",troponin:25,ecg:"Q-волны, ST↓",symptom:"Боль прошла"},{time:720,event:"12 часов",troponin:45,ecg:"Q-волны",symptom:"Усталость"},{time:1440,event:"24 часа",troponin:35,ecg:"Q-волны",symptom:"Улучшение"},{time:10080,event:"7 дней",troponin:2,ecg:"Q-волны",symptom:"Реабилитация"}]},c={id:e,label:i,color:t,nodes:r,links:a,details:s,comparisons:o,evidence:n,timelines:p};export{t as color,o as comparisons,c as default,s as details,n as evidence,e as id,i as label,a as links,r as nodes,p as timelines};
